// App.js
import React, { useEffect, useRef, useState } from 'react';

const fullLines = [
  'name = "Chetanya Makkar"',
  'major = "Computer Science"',
  'minor = "Computational Finance"',
  'gpa = 3.76',
  'school = "University of Maryland"',
];

const sections = ['About', 'Skills', 'Projects', 'Experience', 'Contact'];

export default function App() {
  const [typedLines, setTypedLines] = useState([]);
  const [currentLine, setCurrentLine] = useState('');
  const [lineIndex, setLineIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [loop, setLoop] = useState(0);
  const [activeSection, setActiveSection] = useState('About');
  const refs = useRef({});

  const highlightLine = (line) => {
    const [left, right] = line.split('=');
    const variable = left?.trim();
    const value = right?.trim();

    return (
      <>
        <span className="text-[#9CDCFE]">{variable}</span>
        <span className="text-[#d4d4d4]"> = </span>
        {value?.startsWith('"') ? (
          <span className="text-[#ce9178]">{value}</span>
        ) : (
          <span className="text-[#b5cea8]">{value}</span>
        )}
      </>
    );
  };

  useEffect(() => {
    if (lineIndex < fullLines.length) {
      if (charIndex < fullLines[lineIndex].length) {
        const timeout = setTimeout(() => {
          setCurrentLine(prev => prev + fullLines[lineIndex][charIndex]);
          setCharIndex(i => i + 1);
        }, 40);
        return () => clearTimeout(timeout);
      } else {
        const timeout = setTimeout(() => {
          setTypedLines(prev => [...prev, fullLines[lineIndex]]);
          setCurrentLine('');
          setCharIndex(0);
          setLineIndex(i => i + 1);
        }, 300);
        return () => clearTimeout(timeout);
      }
    } else {
      const timeout = setTimeout(() => {
        setTypedLines([]);
        setCurrentLine('');
        setCharIndex(0);
        setLineIndex(0);
        setLoop(l => l + 1);
      }, 3000);
      return () => clearTimeout(timeout);
    }
  }, [charIndex, lineIndex, loop]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      { threshold: 0.5 }
    );

    sections.forEach(sec => {
      const el = refs.current[sec.toLowerCase()];
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, []);

  return (
    <div className="relative flex bg-[#1e1e1e] text-[#d4d4d4] font-mono text-base">
      <div className="fixed top-0 left-0 h-screen w-24 bg-[#252526] flex flex-col items-center space-y-4 py-6 z-50">
        {sections.map(sec => (
          <div
            key={sec}
            className={`text-xs writing-vertical tracking-wide transition-all duration-200 ${
              activeSection === sec ? 'text-white font-bold' : 'text-gray-400'
            }`}
            style={{ writingMode: 'vertical-rl', transform: 'rotate(180deg)' }}
          >
            {sec}
          </div>
        ))}
      </div>

      <div className="ml-24 flex-1 p-6 space-y-32 scroll-smooth">
        <section id="About" ref={el => (refs.current['about'] = el)} className="min-h-screen">
          <h1 className="text-2xl mb-4">About</h1>
          <div className="space-y-2 text-left">
            {typedLines.map((line, idx) => (
              <div key={`done-${loop}-${idx}`} className="whitespace-pre">{highlightLine(line)}</div>
            ))}
            {lineIndex < fullLines.length && (
              <div className="whitespace-pre border-r-2 border-gray-400 animate-blink">{highlightLine(currentLine)}</div>
            )}
          </div>
        </section>

        <section id="Skills" ref={el => (refs.current['skills'] = el)} className="min-h-screen">
          <h1 className="text-2xl mb-4">Skills</h1>
          <p className="mb-2 font-bold">Programming & Frameworks:</p>
          <ul className="list-disc list-inside text-sm">
            <li>Python, Java, C, OCaml, Rust, SQL, R, JavaScript, MATLAB</li>
            <li>React, Node.js, NumPy, Pandas, Scikit-learn, Tailwind, Jupyter, VS Code</li>
          </ul>
          <p className="mt-4 font-bold">Finance & Modeling:</p>
          <ul className="list-disc list-inside text-sm">
            <li>Portfolio Optimization, Regression, Monte Carlo, A/B Testing, Backtesting</li>
            <li>Excel Modeling, PowerPoint, Quant Research, Risk Metrics</li>
          </ul>
          <p className="mt-4 font-bold">Communication & Strategy:</p>
          <ul className="list-disc list-inside text-sm">
            <li>Teaching & Mentorship, Technical Presentations, Agile Collaboration</li>
          </ul>
        </section>

        <section id="Projects" ref={el => (refs.current['projects'] = el)} className="min-h-screen">
          <h1 className="text-2xl mb-4">Projects</h1>
          <ul className="list-disc list-inside space-y-2 text-sm">
            <li><strong>Flash Crash Analysis:</strong> Regression analysis on high-frequency data confirming Welch & Goyal's predictor limits.</li>
            <li><strong>Portfolio Optimization:</strong> Used Python and convex optimization to build efficient frontiers.</li>
            <li><strong>OCaml Type Checker:</strong> Custom optimizer for OCaml using type inference and syntax trees.</li>
            <li><strong>Solar Power Story:</strong> Visualized Indian solar trends; recognized on Kaggle for storytelling.</li>
          </ul>
        </section>

        <section id="Experience" ref={el => (refs.current['experience'] = el)} className="min-h-screen">
          <h1 className="text-2xl mb-4">Experience</h1>
          <p className="text-sm mb-2">Software Engineering Intern @ BuzzClan</p>
          <p className="text-sm mb-2">Researcher @ UMD Climate Lab — Regression & uncertainty modeling</p>
          <p className="text-sm mb-2">TA for Calculus I & II — Mentored, designed curriculum, improved outcomes</p>
          <p className="text-sm mb-2">Co-founder @ Ruhin Education — Built edtech platform for special needs students</p>
        </section>

        <section id="Contact" ref={el => (refs.current['contact'] = el)} className="min-h-screen">
          <h1 className="text-2xl mb-4">Contact</h1>
          <p>Email: chetanyamakkar99@gmail.com</p>
          <p>LinkedIn: <a className="text-blue-400" href="https://www.linkedin.com/in/chetanyamakkar/" target="_blank">linkedin.com/in/chetanyamakkar</a></p>
          <p>GitHub: <a className="text-blue-400" href="https://github.com/chetanyamakkar11" target="_blank">github.com/chetanyamakkar11</a></p>
        </section>
      </div>
    </div>
  );
}
